        bytes32 indexed feeId,
        address indexed token,
        address recipient,
        uint256 amount
    );

    event Refunded(
        bytes32 indexed transferId,
        address indexed refundAddress,
        address indexed payInToken,
        uint256 amountRefunded
    );

    event ExcessRefunded(
        bytes32 indexed transferId,
        address indexed token,
        address indexed to,
        uint256 amount
    );

    event Recovered(
        bytes32 indexed transferId,
        address indexed token,
        address indexed to,
        uint256 amount
    );
}

